.tv [role=group][hidden]{display:none}.tv li{cursor:pointer}.tv li[aria-expanded]::before{content:"\25B8";display:inline-block;width:1.1em}.tv li[aria-expanded=true]::before{content:"\25BE"}.tv li:not([aria-expanded])::before{content:"";display:inline-block;width:1.1em}.tv [role=group] li{padding:4px 8px}

