document.querySelectorAll('[role=tree]').forEach(tree => {
  const all = () => [...tree.querySelectorAll('[role=treeitem]')].filter(li => !li.parentElement.closest('[role=group][hidden]'));
  const own = li => li.firstChild.textContent.trim();
  const rove = li => { tree.querySelectorAll('[role=treeitem]').forEach(x => x.tabIndex = -1); li.tabIndex = 0; li.focus(); };
  const select = li => { tree.querySelectorAll('[role=treeitem]').forEach(x => x.setAttribute('aria-selected', String(x === li))); };
  const toggle = (li, open) => {
    const g = li.querySelector(':scope > [role=group]'); if (!g) return;
    li.setAttribute('aria-expanded', String(open)); g.hidden = !open;
  };
  const first = tree.querySelector('[aria-selected=true]') || tree.querySelector('[role=treeitem]');
  tree.querySelectorAll('[role=treeitem]').forEach(x => x.tabIndex = -1); first.tabIndex = 0;
  tree.addEventListener('click', e => {
    const li = e.target.closest('[role=treeitem]'); if (!li) return;
    e.stopPropagation(); select(li); rove(li);
    if (li.hasAttribute('aria-expanded')) toggle(li, li.getAttribute('aria-expanded') !== 'true');
  });
  tree.addEventListener('keydown', e => {
    const li = e.target.closest('[role=treeitem]'); if (!li || e.target !== li) return;
    const items = all(), i = items.indexOf(li), open = li.getAttribute('aria-expanded');
    if (e.key === 'ArrowDown') { e.preventDefault(); items[Math.min(items.length - 1, i + 1)] && rove(items[Math.min(items.length - 1, i + 1)]); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); rove(items[Math.max(0, i - 1)]); }
    else if (e.key === 'Home') { e.preventDefault(); rove(items[0]); }
    else if (e.key === 'End') { e.preventDefault(); rove(items[items.length - 1]); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); if (open === 'false') toggle(li, true); else if (open === 'true') rove(li.querySelector('[role=treeitem]')); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); if (open === 'true') toggle(li, false); else { const p = li.parentElement.closest('[role=treeitem]'); if (p) rove(p); } }
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(li); if (open) toggle(li, open !== 'true'); }
  });
});
